from django.db import models

class ItemImage(models.Model):
    lost_item = models.ForeignKey(
        'lost_items.LostItem',
        null=True,
        blank=True,
        on_delete=models.CASCADE,
        related_name='images'
    )
    found_item = models.ForeignKey(
        'found_items.FoundItem',
        null=True,
        blank=True,
        on_delete=models.CASCADE,
        related_name='images'
    )
    image = models.ImageField(upload_to='items/%Y/%m/')
    is_primary = models.BooleanField(default=True)
    # 512-dim normalized float vector generated by CLIP model
    embedding = models.JSONField(
        null=True,
        blank=True,
        help_text="512-dimensional visual feature embedding vector produced by CLIP model"
    )
    uploaded_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        ordering = ['-is_primary', 'id']

    def __str__(self):
        parent = f"LostItem #{self.lost_item_id}" if self.lost_item_id else f"FoundItem #{self.found_item_id}"
        return f"Image #{self.id} for {parent}"
